// -------------------------------------------------------------------------
// AuthFilterExpression.cs
// -------------------------------------------------------------------------
// Provides utility methods to evaluate simple boolean expressions against a
// user context. The expressions may reference predefined variables such as
// "IsAdmin", "user", and "group". This class is used by the web layer to
// filter content based on authentication/authorization rules.
// -------------------------------------------------------------------------
using Bovis.Services.Util;
namespace Bovis.Web.Util
{
    /// <summary>
    /// Static helper for evaluating authentication filter expressions.
    /// </summary>
    internal static class AuthFilterExpression
    {
        /// <summary>
        /// Evaluates a boolean expression using the supplied <see cref="UserContext"/>.
        /// </summary>
        /// <param name="expr">The expression string to evaluate.</param>
        /// <param name="uc">The current user context providing values for variables.</param>
        /// <returns>True if the expression evaluates to true; otherwise false.</returns>
        /// <exception cref="KeyNotFoundException">
        /// Thrown when the expression contains an unknown variable or constant.
        /// </exception>
        public static bool Eval(string expr, UserContext uc)
        {
            // Create a parser that resolves known variables/constants to their runtime values.
            var p = new SimpleExpressionParser((v) => (true,v switch
            {
                "false" => false,
                "true" => true,
                "IsAdmin" => uc.CurrentGroup == UserContext.AdminGroup,
                "is_admin" => uc.CurrentGroup == UserContext.AdminGroup,
                "user" => uc.CurrentUser,
                "group" => uc.CurrentGroup,
                _ => throw new KeyNotFoundException($"BCEE0DF4334E Invalid variable or constant '{v}'")
            })
            );
            p.DoParse(ref expr, out var val);
            return (bool)val;
        }

        // for testing
        /// <summary>
        /// Overload used for testing that evaluates an expression against explicit user and group strings.
        /// </summary>
        /// <param name="expr">The expression string to evaluate.</param>
        /// <param name="user">The user identifier to substitute for the "user" variable.</param>
        /// <param name="group">The group identifier to substitute for the "group" variable.</param>
        /// <returns>True if the expression evaluates to true; otherwise false.</returns>
        /// <exception cref="KeyNotFoundException">
        /// Thrown when the expression contains an unknown variable or constant.
        /// </exception>
        public static bool Eval(string expr, string user, string group)
        {
            // Create a parser that resolves variables using the supplied test values.
            var p = new SimpleExpressionParser((v) => (true,v switch
            {
                "false" => false,
                "true" => true,
                "IsAdmin" => group == "Admin",
                "is_admin" => group == "Admin",
                "user" => user,
                "group" => group,
                _ => throw new KeyNotFoundException($"BC2EA48C527E Invalid variable or constant '{v}'")
            })
            );
            p.DoParse(ref expr, out var val);
            return (bool)val;
        }
    }
